#include <string.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char *P = malloc((size_t)N + 1);
    if (P == NULL) return 0;
    scanf("%s", P);

    for (int k = 1; k <= N / 2; ++k) {
        if (N % k != 0) continue;

        int base[26] = {0};
        for (int i = 0; i < k; ++i)
            ++base[P[i] - 'a'];

        int valid = 1;
        for (int start = k; start < N && valid; start += k) {
            int count[26];
            memcpy(count, base, sizeof(base));

            for (int i = start; i < start + k; ++i)
                --count[P[i] - 'a'];

            for (int c = 0; c < 26; ++c) {
                if (count[c] != 0) {
                    valid = 0;
                    break;
                }
            }
        }

        if (valid) {
            P[k] = '\0';
            printf("%s\n", P);
            free(P);
            return 0;
        }
    }

    puts("*");
    free(P);
    return 0;
}
