#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char *p = malloc((size_t)n + 1);
    if (p == NULL || scanf("%s", p) != 1) {
        free(p);
        return 0;
    }

    for (int len = 1; len <= n / 2; ++len) {
        if (n % len != 0) continue;

        int delta[26] = {0};
        int mismatches = 0;
        int blocks = n / len;
        int valid = 1;

        for (int block = 1; block < blocks; ++block) {
            int previous_start = (block - 1) * len;
            int current_start = block * len;

            for (int i = 0; i < len; ++i) {
                int c = p[previous_start + i] - 'a';
                int old = delta[c]--;
                if (old == 0) ++mismatches;
                else if (old == 1) --mismatches;

                c = p[current_start + i] - 'a';
                old = delta[c]++;
                if (old == 0) ++mismatches;
                else if (old == -1) --mismatches;
            }

            if (mismatches != 0) {
                valid = 0;
                break;
            }
        }

        if (valid) {
            printf("%.*s\n", len, p);
            free(p);
            return 0;
        }
    }

    puts("*");
    free(p);
    return 0;
}
